window.GRIM_PARTS["details-82"]=[{"id":"q0046","name":"治疗药水","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a8313dd7cbaf7.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"在帝国的鼎盛时期，草药师已其丰富的药剂而闻名。不过只有几个配方从那时流传了下来。为了避免它们失传，请酿造冬青果来准备苦药酒，它拥有独特的治疗功能。"},{"title":"任务目标","rows":[{"label":"准备苦药酒","value":10}]},{"title":"完成奖励","rows":[{"label":"厚布","value":"× 10"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0234"],"english":"Healing Potion"},{"id":"q0047","name":"瘟疫的载体","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a765e09971577.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"瘟疫第一次出现时，帝国的骑士勇敢地对抗被感染的人，并帮助生活在那里的农夫。但瘟疫一个个带走了他们。现在，那些曾经高贵的战士开始狩猎那些原本需要他们保护的人。被咒骑士无法得到救赎，所以遇到他们格杀勿论。这片土地上的邪恶已经够多了。"},{"title":"任务目标","rows":[{"label":"击杀被咒骑士","value":10}]},{"title":"完成奖励","rows":[{"label":"线","value":"× 10"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0259"],"english":"Carriers of the Plague"},{"id":"q0048","name":"迷宫","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/ad81a0601f686.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"骑士团的斥候报告称，他们经常在东边的墓地见到福金出没。我不知道他在那边藏了什么东西，希望你能帮我打探一下。记住：墓地不再是以前的安详之地。"},{"title":"任务目标","rows":[{"label":"查清福金在隐藏什么","value":1}]},{"title":"完成奖励","rows":[{"label":"炉架","value":"× 7"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0257"],"english":"Labyrinth"},{"id":"q0049","name":"钥匙的主人","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a4f9d128bcd2b.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"被弃骑士团已经很久没有出现在人们的视野中，继续这样下去也很好。我们不需要另一场战争。前往他们的地下城并阻止他们。地下城的入口锁上了，所以你需要先找到看守者并拿到他的钥匙。"},{"title":"任务目标","rows":[{"label":"击杀看守者","value":1},{"label":"前往被弃者地下城","value":1}]},{"title":"完成奖励","rows":[{"label":"蘑菇浸剂","value":"× 2"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0045"],"english":"Master of the Keys"},{"id":"q0050","name":"两人之军","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/aa3545c55b646.webp","stats":[{"label":"委托人","value":"福金领主"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"我知道科尔是怎么跟你说我的。我会如实回答：那是真的，但又不是全部的真相。那个傻瓜不知道自己面对的是谁。请允许我为你展示真相。我会在地图上标记的地方等你。来吧，这件事远比你我更加重要。"},{"title":"任务目标","rows":[{"label":"听听福金要说什么","value":1}]},{"title":"完成奖励","rows":[{"label":"圣彼得药酒","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0034"],"english":"Army of Two"},{"id":"q0051","name":"回归","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a355c6ec74ac2.webp","stats":[{"label":"委托人","value":"阿莱娜"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"我叫阿莱娜，但你的名字对我无足轻重。我知道你被赶出了帝国，游荡在幽灵和被咒者之间。你有没有想过重新回到城市，不必每天为了活下去而苦苦挣扎？或者，对那些驱逐你的人展开复仇？我可以帮你，但天下没有免费的午餐。不妨听下我的提议：我帮你通过城门，你帮我做几件事。怎么样？然后你应该建造神庙。它可以帮你找到其他决心返回城市的流亡者。"},{"title":"任务目标","rows":[{"label":"建造神庙","value":1}]},{"title":"完成奖励","rows":[{"label":"1 级控制卷轴","value":"× 2"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0010"],"english":"Return"},{"id":"q0052","name":"首个骑士团","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/ada67aa456452.webp","stats":[{"label":"委托人","value":"阿莱娜"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"你终于把神庙建好了吗？现在你可以加入骑士团了。帝国守卫在密切监视所有他们怀疑的人，这一点不用我告诉你了吧。任何能证明你属于骑士团的文件都会增加你的分量。你的骑士团规模越大、财力越雄厚，为你敞开的大门就越多。"},{"title":"任务目标","rows":[{"label":"加入骑士团（或建立自己的骑士团）","value":1}]},{"title":"完成奖励","rows":[{"label":"流星锤","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0706"],"english":"First Order"},{"id":"q0053","name":"秘密知识","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a0f3113d1139f.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"仔细翻阅你在冒险中找到的所有书籍。从特定武器的用法到如何利用敌人的弱点，它们的内容无所不包。但如果这还不够......我听说在赫拉特祭坛打碎灵魂碎片可以让你进一步学习更多技能和知识。但是请当心：灵魂碎片虽然是种更强大的力量，但却非常危险。"},{"title":"任务目标","rows":[{"label":"组装祭坛","value":1}]},{"title":"完成奖励","rows":[{"label":"装小恐狼的笼子 · 普通","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0288"],"english":"Secret Knowledge"},{"id":"q0054","name":"动物育婴室","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/adfb2cc4995e7.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"你成功驯服了一头恐狼。干得不错。不过如果你打算真正培育这种动物，那你需要一个更大的恐狼棚。你可以在地下城中找到它的稀有部件。"},{"title":"任务目标","rows":[{"label":"将恐狼棚升到第 2 级","value":1}]},{"title":"完成奖励","rows":[{"label":"恐狼零食","value":"× 5"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0319"],"english":"Animal Nursery"},{"id":"q0055","name":"被咒者的家","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a1c2bd3d070d5.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"古老的力量已经从沉睡中苏醒。你也能感觉到吗？但也许可以让它为我们所用。不久前，封锁了几百年的地下墓穴的入口再次打开了。当你听到它们的召唤时，就前往地下墓穴吧。"},{"title":"任务目标","rows":[{"label":"访问地下墓穴","value":1}]},{"title":"完成奖励","rows":[{"label":"恐怖卷轴","value":"× 3"},{"label":"苦药酒","value":"× 5"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0018","i0039"],"english":"Home of the Damned"},{"id":"q0056","name":"陷入黑暗","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/ae241c9a3c7f7.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"也许你应该当心，其他骑士团的叛徒可能会阻挡你的路。但他们对你来说不是问题，对吗？"},{"title":"任务目标","rows":[{"label":"完成地下墓穴的第二层","value":1}]},{"title":"完成奖励","rows":[{"label":"冻结卷轴","value":"× 3"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0016"],"english":"Descent into Darkness"},{"id":"q0057","name":"各自行动","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a7f93b2a4251a.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"你的努力值得称赞。在你战斗的时候，我利用这段时间研究了墙上的铭文。它们比想象的要重要得多。但是承认吧：你也不会空手离开地下墓穴。所以去拿属于你的东西吧。"},{"title":"任务目标","rows":[{"label":"完成地下墓穴的第四层","value":1}]},{"title":"完成奖励","rows":[{"label":"曼德拉药酒","value":"× 5"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0038"],"english":"To Each Their Own"},{"id":"q0058","name":"死亡之路","category":"quests","subcategory":"第 III 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a7f93b2a4251a.webp","stats":[{"label":"委托人","value":"福金领主"},{"label":"章节","value":"第 III 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"也许你并不信任我，但我们的目标一致。我们必须阻止冷酷国王毁灭这个世界。无名之神的专家最后出现的地点是东部墓穴。你去探查一下。搜寻所有可以帮助我们的情报。我们的时间不多了。"},{"title":"任务目标","rows":[{"label":"调查墓穴","value":1}]},{"title":"完成奖励","rows":[{"label":"曼德拉药酒","value":"× 2"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0038"],"english":"In Death's Tracks"},{"id":"q0059","name":"活靶子","category":"quests","subcategory":"第 III 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a7ece85b7f469.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 III 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"如果你在墓穴中找到的那个老人知道死亡之夜的事，那我会尽量找到他。现在，我们需要继续你的教育。\n 你不应该徒手对付所有敌人。许多情况下，从远处攻击敌人更加明智。就拿瘟疫之卵来说吧：它们的毒性超强，但一把猎弓就能轻松解决它们。现在去地下城用一些箭术练习来巩固你的知识吧。"},{"title":"任务目标","rows":[{"label":"制作猎弓","value":1},{"label":"用猎弓杀死瘟疫之卵","value":10}]},{"title":"完成奖励","rows":[{"label":"弓弦","value":"× 3"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0253"],"english":"Live Target"},{"id":"q0060","name":"保护神祠","category":"quests","subcategory":"第 III 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/ab0bffa2eba03.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 III 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"流亡者！我希望你的箭术课程进展顺利。我现在需要你和你的弓箭。这片土地上曾经有许多朝拜赫拉特的建筑，但瘟疫降临后，大部分都被拆除了。我不知道为什么要拆除这些地方，但它们是唯一可以加强幸存者信念的地方。现在有一座神祠正面临拆除危机。请去保护它。"},{"title":"任务目标","rows":[{"label":"击退对神祠的进攻","value":1}]},{"title":"完成奖励","rows":[{"label":"煤炭","value":"× 5"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0248"],"english":"Defending the Shrine"},{"id":"q0061","name":"小心脚下","category":"quests","subcategory":"第 III 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a0231ced90a8d.webp","stats":[{"label":"委托人","value":"福金领主"},{"label":"章节","value":"第 III 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"在战争中，你必须利用所有优势，特别是当敌人比你强的时候。就从基础知识开始，布置一个陷阱吧。它虽然简单，但却十分有效。不过当心，别踏入自己的陷阱里。"},{"title":"任务目标","rows":[{"label":"用陷阱捉住敌人","value":10}]},{"title":"完成奖励","rows":[{"label":"硫磺","value":"× 5"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0249"],"english":"Watch your step"},{"id":"q0062","name":"黑暗仪式","category":"quests","subcategory":"第 III 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a3c66c927a637.webp","stats":[{"label":"委托人","value":"福金领主"},{"label":"章节","value":"第 III 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"在对抗冷酷国王的战争中，皇帝的军队在森林中搜寻黑暗专家。专家们学会了在骑士的鼻子下偷偷溜掉，但把他们的财物藏起来就困难多了。他们召唤了无名之神，造出了可以在白天隐形的秘密藏匿处。你依然可以在最浓密和最危险的丛林中找到他们的魔法地窖。当夜幕降临时，去松树林寻找其中一个秘密地窖吧。"},{"title":"任务目标","rows":[{"label":"寻找并搜查夜晚地窖","value":2}]},{"title":"完成奖励","rows":[{"label":"锁链","value":"× 10"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0258"],"english":"Dark Ritual"},{"id":"q0063","name":"基本防御","category":"quests","subcategory":"第 III 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/aeab02dd4bb5e.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 III 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"我听说你只用一个车把就击败了对手。但你知道如何保护自己吗？就算一个简单的木盾也能多次拯救许多老练的战士。你也应该学会用盾。只要学会在合适的时机举盾，你就可以保护自己免遭最致命的攻击！"},{"title":"任务目标","rows":[{"label":"制作轻盾","value":1},{"label":"用护盾格挡攻击","value":500}]},{"title":"完成奖励","rows":[{"label":"铁帽","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i1022"],"english":"Basic Defense"},{"id":"q0064","name":"剑与石","category":"quests","subcategory":"第 III 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a355c6ec74ac2.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 III 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"我决定去骑士团的图书馆帮你找找看。关于你要找的那个老人，图书馆里几乎没有相关记录，但我却找到了点别的东西。那是一座古代皇陵。国王下葬时都会有珍宝陪葬。虽然在瘟疫之前我不会派你去玷污如此神圣的墓葬，但你现在比他更需要使用这些财宝。"},{"title":"任务目标","rows":[{"label":"搜寻陵墓","value":1}]},{"title":"完成奖励","rows":[{"label":"2 级控制卷轴","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0009"],"english":"Blade and Stone"},{"id":"q0065","name":"配制药剂","category":"quests","subcategory":"第 III 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a2a0174eb5237.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 III 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"曼德拉草是野外最令人着迷的植物之一。有许多异教仪式都会用到它的根茎，但我们对它的另一种用途更感兴趣。曼德拉草是一种特别药酒的重要成分。这种药酒可以疗伤并提高你的攻击速度。但是别喝太多，它有毒性。"},{"title":"任务目标","rows":[{"label":"准备曼德拉药酒","value":10}]},{"title":"完成奖励","rows":[{"label":"陷阱","value":"× 5"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0159"],"english":"Potion Brewing"},{"id":"q0066","name":"死亡战争","category":"quests","subcategory":"第 III 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a63cadea2eabd.webp","stats":[{"label":"委托人","value":"马雷·撒图克"},{"label":"章节","value":"第 III 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"我一直在回想我们之前的比试。我需要找回自己的荣誉，证明我的剑术比你更强。重新比一场怎么样？但不是一对一。这次，我准备了一些更有趣的东西。"},{"title":"任务目标","rows":[{"label":"赢得比赛","value":1}]},{"title":"完成奖励","rows":[{"label":"长筒靴","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i1026"],"english":"War of the Dead"},{"id":"q0067","name":"围城","category":"quests","subcategory":"第 III 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a4fdea351a04c.webp","stats":[{"label":"委托人","value":"福金领主"},{"label":"章节","value":"第 III 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"你也许在瘟疫之地见过其他流亡者的家。他们和你一样，经常出去冒险，所以家里的财物无人看管。你知道我是什么意思吧？在这里，强者生存。带上一些炸药包，它们适合破门而入。"},{"title":"任务目标","rows":[{"label":"炸掉围墙","value":2}]},{"title":"完成奖励","rows":[{"label":"法兰锤","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0700"],"english":"Siege"},{"id":"q0068","name":"怪物出现","category":"quests","subcategory":"第 III 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a856da81865b1.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 III 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"我的努力终于有了成果。斥候报告称他们发现了一位佩剑老人，剑上刻有无名之神的符文。他可能就是你要找的人。他最后一次出现在北方之地。给你的马配上马鞍去寻找那个老人吧，以免被人捷足先登。"},{"title":"任务目标","rows":[{"label":"追寻老人的踪迹","value":1}]},{"title":"完成奖励","rows":[{"label":"锁环甲护手","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i1024"],"english":"Here There Be Monsters"},{"id":"q0069","name":"毒药...","category":"quests","subcategory":"第 III 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a8230102abb97.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 III 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"很抱歉我的信息有误。我会继续调查，但我现在需要你的帮助。北方之地生活着一种危险的飞行恐怖蝙蝠。它们速度很快，有剧毒。我们的记录中对它们所提甚少。你能击杀几只，然后给我描述下它们的体型和习性吗？"},{"title":"任务目标","rows":[{"label":"制作轻弩","value":1},{"label":"使用轻弩击杀恐怖蝙蝠","value":10}]},{"title":"完成奖励","rows":[{"label":"锡","value":"× 10"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0215"],"english":"Poison..."},{"id":"q0070","name":"工匠","category":"quests","subcategory":"第 III 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/add882971e1e6.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 III 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"北方之地蕴含着丰富的硬木和铁矿石资源。既然你已经开始调查该地区，那么你应该存储这些资源。它们可以用来制作更高级的装备，所以准备干点重活吧。"},{"title":"任务目标","rows":[{"label":"开采铁矿石","value":100},{"label":"砍伐原桦木","value":100}]},{"title":"完成奖励","rows":[{"label":"铜腿甲","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i1025"],"english":"Craftsman"},{"id":"q0071","name":"...解毒剂","category":"quests","subcategory":"第 III 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/abad760816ad7.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 III 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"你的描述相当详细，我会仔细研究。与此同时，我还有一件小事想请你帮忙。北方之地生长着许多品种的蘑菇，我对墓地蘑菇特别有兴趣。这种蘑菇有剧毒，但妥善处理的话，可以用作解毒剂的材料。请准备几份药剂，然后把你的实验结果告诉我。"},{"title":"任务目标","rows":[{"label":"准备蘑菇浸剂","value":10}]},{"title":"完成奖励","rows":[{"label":"浆果饮料","value":"× 10"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0078"],"english":"... and antidote"},{"id":"q0072","name":"如何消灭死亡","category":"quests","subcategory":"第 III 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a3365f42e58b4.webp","stats":[{"label":"章节","value":"第 III 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"我听说你在找我。我也知道你和本地的强盗并不是朋友。但我担心他们会找到并来骚扰我。我有个提议：帮我把他们从我家里永远地赶出去，我就把你想知道的事全盘托出。你意下如何？"},{"title":"任务目标","rows":[{"label":"拯救老人","value":1}]},{"title":"完成奖励","rows":[{"label":"战争刀","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0677"],"english":"How to Kill Death"},{"id":"q0073","name":"马厩","category":"quests","subcategory":"第 III 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/af20f3f5bc963.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 III 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"我猜你已经厌倦了去哪儿都要步行。马匹可以帮你更快地前往远方。但好马配马厩。在全盛时期，被弃骑士团拥有自己的骑兵。你应该可以在他们的地下城里找到马厩的部分部件。"},{"title":"任务目标","rows":[{"label":"组装马厩","value":1}]},{"title":"完成奖励","rows":[{"label":"燕麦种","value":"× 10"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0207"],"english":"Stable"},{"id":"q0074","name":"骑师","category":"quests","subcategory":"第 III 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a6bba9f95b751.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 III 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"马厩建好了，现在只剩一件事：驯马。在瘟疫之地，找到马儿最好的地方就是破损大车。遗憾的是，之前的马主已经用不到它们了。马儿天生易受惊吓，所以如果第一次驯马失败的话，也不要太吃惊。"},{"title":"任务目标","rows":[{"label":"驯马","value":1}]},{"title":"完成奖励","rows":[{"label":"绷带","value":"× 5"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0040"],"english":"Horseman"},{"id":"q0075","name":"被遗弃的被弃者","category":"quests","subcategory":"第 III 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a353aeb3cf1e5.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 III 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"通往地下城下层的门锁住了，但钥匙打不开这扇门。只凭自己空想，是没办法找出那扇门的秘密的。所以你得找个知道内情的人并审问他。这里有不少被骑士团抛弃的隐士。他们不难找，但你知道怎么让他们开口吗？我不能再告诉你更多了。你只能凭借自己的良心决定。"},{"title":"任务目标","rows":[{"label":"组装酷刑椅","value":1}]},{"title":"完成奖励","rows":[{"label":"青铜钉","value":"× 10"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0230"],"english":"Forsook from the Forsaken"},{"id":"q0076","name":"艾森博格领主","category":"quests","subcategory":"第 III 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/aef8a8201cb4f.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 III 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"如果被弃者真的打算和帝国开战，那我们必须阻止他们。这个世间有两个争斗的神灵就已经够乱的了。请全力以赴，阻止艾森博格。"},{"title":"任务目标","rows":[{"label":"在被弃者地下城中击杀艾森博格","value":1}]},{"title":"完成奖励","rows":[{"label":"骨制棒子","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0638"],"english":"Master Eisenborg"},{"id":"q0077","name":"巧手铁匠","category":"quests","subcategory":"第 III 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a4bf3d5911095.webp","stats":[{"label":"委托人","value":"马雷·撒图克"},{"label":"章节","value":"第 III 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"你得一直比敌人多走一步。用铜锁子甲换掉你的软铠甲。在战斗中，苦药酒比什么绷带都管用，你的剑是最锋利的语言。所以你需要磨石。在战斗中，武器和技能同样重要。"},{"title":"任务目标","rows":[{"label":"组装磨石","value":1}]},{"title":"完成奖励","rows":[{"label":"武器油","value":"× 2"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0139"],"english":"Skilled Blacksmith"}];
